@startuml

enum BookingStatus {
  PRELIMINARY
  FINALIZED
  CONFIRMED
  CANCELLED_BY_TRAVELLER
  CANCELLED_BY_HOTEL
}

enum PaymentType {
  PREPAID
  PAID_AT_HOTEL
}

class HotelBookingManager {
}

class Traveller {
  + name : string
  + billingInformation : string
  + companyName : string
  + companyAddress : string
  + reliabilityRating : float
}

class TravelPreference {
  + preference : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : string
  + minimumHotelRating : int
  + tentativeBudget : float
}

class Booking {
  + bookingId : int
  + cancellationDeadline : date
  + bookingStatus : BookingStatus
  + paymentType : PaymentType
  + creditCardInformation : string
}

class SpecialOffer {
  + price : float
  + cityArea : string
  + hotelRating : int
}

class Hotel {
  + address : string
  + city : string
}

class HotelChain {
}

class RoomType {
  + type : string
  + isFullyBooked : boolean
}

Traveller "1" -- "*" TravelPreference
Traveller "1" -- "*" Booking
Traveller "1" -- "*" SearchCriteria
HotelBookingManager "1" -- "*" Traveller
HotelBookingManager "1" -- "*" Booking
HotelBookingManager "1" -- "*" SpecialOffer
HotelBookingManager "1" -- "*" Hotel
Hotel "0..1" -- "*" HotelChain
Hotel "1" -- "*" Booking
Hotel "1" -- "*" RoomType

Booking "1" -- "0..5" SpecialOffer : receives
Booking "1" -- "1" SearchCriteria : based on

@enduml

